starter.solution.cpp:
#include <concepts>

template <typename T>
T half(T value)
{
    return value / 2;
}

solution.solution.cpp:
#include <concepts>

template <std::integral T>
T half(T value)
{
    return value / 2;
}

unitTests:
template <typename T> concept CanHalf = requires(T t) { half(t); };
static_assert(CanHalf<int> && CanHalf<long long> && CanHalf<unsigned char>, "half should accept integer types");
static_assert(!CanHalf<double> && !CanHalf<float>, "half should reject floating-point types: constrain it with std::integral");

TEST("still halves") { CHECK_EQ(half(10), 5); CHECK_EQ(half(7), 3); CHECK_EQ(half(100LL), 50LL); }

